node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('ORD-CCC96C');
console.log('Order:', JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = ?\").all('ORD-CCC96C');
console.log('Order Items:', JSON.stringify(items, null, 2));

// Get payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = ?\").all('ORD-CCC96C');
console.log('Payments:', JSON.stringify(payments, null, 2));

// Get fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = ?\").all('ORD-CCC96C');
console.log('Fulfillments:', JSON.stringify(fulfillments, null, 2));
"
